 function drawProjects(){let list=projects.filter(p=>(selected==='all'||p.id===selected)&&p.name.toLowerCase().includes(search.toLowerCase()));page.innerHTML=header('Projects','One portfolio. A clear home for every project.','<button class="secondary" data-action="backup">Export backup</button><button class="primary" data-action="new-project">+ New project</button>')+filters()+`<div class="portfolio">${list.map(p=>{let tasks=issues.filter(t=>t.projectId===p.id),team=teams.find(t=>t.id===p.teamId),pm=members.find(m=>m.id===p.managerId);return `<article class="panel portfolio-card"><div class="portfolio-top"><span class="project-symbol" style="background:${p.color}">▱</span><span class="badge">${esc(p.status)}</span><button class="text-btn" data-project-edit="${p.id}" aria-label="Edit ${esc(p.name)}">Edit</button></div><small>${esc(ProjectAPI.projectKey(p))}</small><h2>${esc(p.name)}</h2><p>${esc(p.description||'No description yet.')}</p><div class="project-owner">${avatar(pm)}<div>${esc(p.manager)}<small>Project manager</small></div></div><div class="project-team-label">${esc(team?.name||'No team assigned')}</div><div class="member-stack">${(p.memberIds||[]).map(id=>avatar(members.find(m=>m.id===id))).join('')}</div><div class="portfolio-progress"><span>${tasks.filter(t=>t.status==='Done').length} / ${tasks.length} tasks complete</span><b>${Planning.progress(tasks)}%</b></div><div class="progress-track"><i style="width:${Planning.progress(tasks)}%"></i></div><div class="portfolio-date">${shortDate(p.startDate)} – ${shortDate(p.endDate)}</div><div class="portfolio-links"><button data-project-plan="${p.id}">View tasks</button><button data-project-docs="${p.id}">Documents (${documents.filter(d=>d.projectId===p.id&&!d.trashed).length})</button><button data-project-events="${p.id}">Calendar</button></div></article>`}).join('')||'<p class="empty">No projects match your search.</p>'}</div>`}
 function drawDocuments(){let list=documents.filter(d=>!!d.trashed===trash&&(selected==='all'||d.projectId===selected)&&(d.name+' '+d.category).toLowerCase().includes(search.toLowerCase()));page.innerHTML=header('Project documents','Keep briefs, specifications, and release files with their project.','<button class="primary" data-action="new-doc">+ Add document</button>')+filters(`<button class="secondary" data-action="toggle-trash">${trash?'View documents':'Trash ('+documents.filter(d=>d.trashed).length+')'}</button>`)+`<div class="panel document-table"><div class="document-head"><span>DOCUMENT</span><span>PROJECT</span><span>UPDATED</span><span>ACTIONS</span></div>${list.map(d=>`<article class="document-row"><div class="document-name"><span class="file-symbol">${d.kind==='note'?'≡':'▤'}</span><div><button class="task-title" data-doc-open="${d.id}">${esc(d.name)}</button><small>${esc(d.category)} · ${d.kind==='note'?'Workspace note':formatSize(d.size)}</small></div></div><span>${esc(projects.find(p=>p.id===d.projectId)?.name||'')}</span><time>${shortDate(d.updated.slice(0,10))}</time><div class="row-actions">${trash?`<button data-doc-restore="${d.id}">Restore</button>`:`<button data-doc-edit="${d.id}">Edit</button><button data-doc-download="${d.id}">Download</button><button data-doc-trash="${d.id}" aria-label="Move ${esc(d.name)} to trash">Trash</button>`}</div></article>`).join('')||`<div class="work-empty"><span>▤</span><h2>${trash?'Trash is empty':'A home for your project knowledge'}</h2><p>${trash?'Removed documents can be restored here.':'Upload a file or write a document. Files are stored with this project on the server.'}</p>${trash?'':'<button class="secondary" data-action="new-doc">Add your first document</button>'}</div>`}</div>`}

