 const types=['Release','Meeting','Milestone','Other'];const eventClass=t=>t.toLowerCase();
 function eventList(){return events.filter(e=>!e.cancelled&&(selected==='all'||e.projectId===selected)&&(eventType==='all'||e.type===eventType)&&e.title.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
