 function drawCalendar(){let first=new Date(year,month,1),offset=(first.getDay()+6)%7,start=new Date(year,month,1-offset),days=new Date(year,month+1,0).getDate(),rows=Math.ceil((offset+days)/7),monthName=first.toLocaleDateString('en-US',{month:'long',year:'numeric'}),list=eventList();let dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 page.innerHTML=header('Event calendar','Releases, meetings, and milestones—planned together.','<button class="primary" data-action="new-event">+ New event</button>')+filters(`<select id="event-type" aria-label="Filter event type"><option value="all">All event types</option>${types.map(t=>`<option${t===eventType?' selected':''}>${t}</option>`).join('')}</select>`)+`<div class="calendar-heading"><div><button class="icon-btn" data-month="-1" aria-label="Previous month">‹</button><h2>${monthName}</h2><button class="icon-btn" data-month="1" aria-label="Next month">›</button><button class="secondary" data-action="today">Today</button></div><div class="plan-tabs"><button data-calendar-mode="month" class="${calendarMode==='month'?'active':''}">Month</button><button data-calendar-mode="agenda" class="${calendarMode==='agenda'?'active':''}">Agenda</button></div></div>`;
 if(calendarMode==='month'){page.innerHTML+=`<div class="panel calendar-scroll"><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:rows*7},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);let k=dateKey(d),daily=list.filter(e=>e.date<=k&&e.endDate>=k);return `<div class="calendar-day ${d.getMonth()!==month?'outside':''} ${k===today()?'is-today':''}"><button class="day-number" data-event-date="${k}" aria-label="Add event on ${k}">${d.getDate()}</button>${daily.map(eventChip).join('')}</div>`}).join('')}</div></div>`}else{let begin=dateKey(first),end=dateKey(new Date(year,month+1,0)),agenda=list.filter(e=>e.date<=end&&e.endDate>=begin);page.innerHTML+=`<div class="panel agenda">${agenda.map(e=>`<article><div class="agenda-date">${shortDate(e.date)}<small>${e.allDay?'All day':e.time+' – '+e.endTime}</small></div><div><span class="event-label ${eventClass(e.type)}">${e.type}</span><button class="task-title" data-event-edit="${e.id}">${esc(e.title)}</button><p>${esc(projects.find(p=>p.id===e.projectId)?.name||'Workspace')} · ${esc(e.location||'No location')}</p></div><div class="member-stack">${e.attendees.map(id=>avatar(members.find(m=>m.id===id))).join('')}</div></article>`).join('')||'<p class="empty">No events this month. Add a release, meeting, or milestone.</p>'}</div>`}page.innerHTML+=`<div class="calendar-key">${types.map(t=>`<span class="event-label ${eventClass(t)}">${t}</span>`).join('')}<small>Events retain their timezone. No invitations are sent.</small></div>`}
 function field(label,name,value='',type='text',required=true){return `<label for="wm-${name}">${label}</label><input id="wm-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='text'?'maxlength="160"':''}>`}
