 async function commit(message,file){await persist(file);renderBefore();updateTeamSummary();draw();modal.close();toast(message)}
 function editProject(id){let p=projects.find(p=>p.id===id)||{name:'',description:'',manager:'Bin Li',teamId:teams[0]?.id,status:'Active',startDate:today(),endDate:today(),color:'#aaa0ce'};editDialog(id?'Edit project':'New project',field('Project name','name',p.name)+`<label for="wm-projectKey">Project key</label><input id="wm-projectKey" name="projectKey" value="${esc(ProjectAPI.projectKey(p))}" required pattern="[A-Z][A-Z0-9]{1,15}" maxlength="16" placeholder="REV" ${id&&issues.some(t=>t.projectId===id)?'readonly':''}><small>2–16 uppercase letters or numbers, starting with a letter. Locked after the first ticket.</small>`+area('Ticket types (one per line)','ticketTypes',(p.ticketTypes||['Task','Bug','Subtask']).join('\n'))+`<small>Add, rename or remove types here. Types used by existing tickets must be kept.</small>`+area('Description','description',p.description)+`<div class="field-grid"><div>${select('Project manager','managerId','<option value="">Unassigned</option>'+options(members,p.managerId))}</div><div>${select('Team','teamId','<option value="">No team</option>'+options(teams,p.teamId))}</div><div>${field('Start date','startDate',p.startDate,'date')}</div><div>${field('End date','endDate',p.endDate,'date')}</div><div>${select('Status','status',['Active','On hold','Completed','Archived'].map(s=>`<option${s===p.status?' selected':''}>${s}</option>`).join(''))}</div><div>${field('Project color','color',p.color,'color')}</div></div>`+checks('Project members','memberIds',members,p.memberIds||[]),async f=>{let v=Object.fromEntries(f);v.memberIds=f.getAll('memberIds');v.projectKey=v.projectKey.trim().toUpperCase();v.ticketTypes=v.ticketTypes.split(/\r?\n/).map(t=>t.trim()).filter(Boolean);if(!/^[A-Z][A-Z0-9]{1,15}$/.test(v.projectKey))throw Error('Use a project key such as REV (2–16 uppercase letters or numbers).');if(projects.some(x=>x.id!==id&&ProjectAPI.projectKey(x)===v.projectKey))throw Error('This project key is already used.');if(!v.ticketTypes.length||v.ticketTypes.length>30||v.ticketTypes.some(t=>! /^[A-Za-z][A-Za-z0-9 _-]{0,63}$/.test(t))||new Set(v.ticketTypes.map(t=>t.toLowerCase())).size!==v.ticketTypes.length)throw Error('Enter up to 30 distinct ticket types, starting with a letter.');if(issues.some(t=>t.projectId===id&&!v.ticketTypes.includes(t.kind)))throw Error('Reassign tickets before removing their type.');if(v.endDate<v.startDate)throw Error('End date must be on or after the start date.');if(!v.name.trim())throw Error('Enter a project name.');let m=members.find(m=>m.id===v.managerId);Object.assign(v,{manager:m?.name||'Unassigned',managerId:m?.id||null,name:v.name.trim(),date:shortDate(v.startDate),end:shortDate(v.endDate),initials:(m?.name||'Unassigned').split(' ').map(n=>n[0]).join(''),lead:m?.name||'Unassigned',team:0});if(id)Object.assign(p,v);else projects.push({...v,id:uid('PRJ')});await commit('Project saved')})}
