 function editDoc(id){if(!projects.length){toast('Create a project first.');return;}let d=documents.find(d=>d.id===id)||{name:'',projectId:selected==='all'?projects[0]?.id:selected,category:'Brief',kind:'note',content:''};editDialog(id?'Edit document':'Add document',field('Document title','name',d.name)+select('Project','projectId',options(projects,d.projectId))+select('Category','category',['Brief','Specification','Design','Release','Meeting notes','Other'].map(s=>`<option${s===d.category?' selected':''}>${s}</option>`).join(''))+select('Document type','kind',`<option value="note"${d.kind==='note'?' selected':''}>Written document</option><option value="file"${d.kind==='file'?' selected':''}>Uploaded file</option>`)+`<div id="doc-written">${area('Content','content',d.content||'')}</div><div id="doc-upload"><label for="wm-file">${id?'Replace file (optional)':'Choose file'} · up to 25 MB</label><input id="wm-file" name="file" type="file"><p>${esc(d.fileName||'Files are stored on the server.')}</p></div>`,async f=>{let kind=f.get('kind'),file=f.get('file'),docId=id||uid('doc'),v={id:docId,name:f.get('name').trim(),projectId:f.get('projectId'),category:f.get('category'),kind,content:kind==='note'?f.get('content'):'',updated:new Date().toISOString(),trashed:false};if(!v.name)throw Error('Enter a document title.');if(kind==='file'){if(!file.size&&(!id||d.kind!=='file'))throw Error('Choose a file to upload.');if(file.size>26214400)throw Error('Choose a file smaller than 25 MB.');Object.assign(v,file.size?{size:file.size,fileName:file.name,mime:file.type}:{size:d.size,fileName:d.fileName,mime:d.mime})}if(id)Object.assign(d,v);else documents.push(v);await commit('Document saved',kind==='file'&&file.size?{id:docId,file}:undefined)});let toggle=()=>{let file=$('#wm-kind').value==='file';$('#doc-written').classList.toggle('hidden',file);$('#doc-upload').classList.toggle('hidden',!file)};$('#wm-kind').onchange=toggle;toggle()}
 function editEvent(id,date,defaultType='Meeting'){if(!projects.length){toast('Create a project first.');return;}let e=events.find(e=>e.id===id)||{title:'',type:defaultType,projectId:selected==='all'?projects[0]?.id:selected,date:date||today(),endDate:date||today(),time:'09:00',endTime:'10:00',allDay:false,attendees:[],location:'',description:''};editDialog(id?'Edit event':'New event',field('Event title','title',e.title)+`<div class="field-grid"><div>${select('Event type','type',types.map(t=>`<option${t===e.type?' selected':''}>${t}</option>`).join(''))}</div><div>${select('Project','projectId',options(projects,e.projectId))}</div><div>${field('Start date','date',e.date,'date')}</div><div>${field('End date','endDate',e.endDate,'date')}</div></div><label class="inline-check"><input type="checkbox" name="allDay" id="wm-allDay"${e.allDay?' checked':''}> All-day event</label><div class="field-grid" id="event-times"><div>${field('Start time','time',e.time,'time')}</div><div>${field('End time','endTime',e.endTime,'time')}</div></div>`+field('Location or meeting link (optional)','location',e.location,'text',false)+area('Description','description',e.description)+checks('Attendees','attendees',members,e.attendees),async f=>{let v=Object.fromEntries(f);v.title=v.title.trim();v.allDay=f.has('allDay');v.attendees=f.getAll('attendees');v.cancelled=false;if(!v.title)throw Error('Enter an event title.');if(v.endDate<v.date||(!v.allDay&&v.endDate===v.date&&v.endTime<=v.time))throw Error('The event must end after it starts.');if(id)Object.assign(e,v);else events.push({...v,id:uid('event')});await commit('Event saved')},id?`<button type="button" class="danger-btn" data-event-cancel="${id}">Cancel event</button>`:'');let toggle=()=>{$('#event-times').classList.toggle('hidden',$('#wm-allDay').checked);$('#event-times').querySelectorAll('input').forEach(i=>i.required=!$('#wm-allDay').checked)};$('#wm-allDay').onchange=toggle;toggle()}
